// Build Claude request to tailor resume for this specific job

const MASTER_RESUME = `
HERSH MALIK | Product & Technology Leadership
LinkedIn: linkedin.com/in/hershmalik | Washington DC Metro Area

SUMMARY
Senior product and program leader with 12 years at Goldman Sachs, Morgan Stanley, and Coinbase driving fintech infrastructure, compliance technology, and production AI systems. Built RAG-based compliance pipelines, MCP agentic workflows, and n8n automation frameworks at scale. Columbia MBA. Track record of shipping 0-to-1 products and leading cross-functional orgs in regulated environments.

EXPERIENCE

Coinbase | Senior Director of Product (most recent role)
- Led product strategy for compliance infrastructure serving 100M+ users across 100+ jurisdictions
- Built and deployed production RAG system for regulatory document analysis, reducing compliance review time 60%
- Architected MCP agentic workflow platform enabling autonomous compliance monitoring and alerting
- Drove n8n-based automation reducing manual ops work by 40% across compliance and risk teams
- Managed $25M product budget and 3 cross-functional squads (PM, Eng, Data)

Goldman Sachs | Vice President, Product & Technology
- Owned product roadmap for transaction monitoring and AML/KYC systems processing $2T+ annually
- Launched real-time fraud detection platform integrating ML models into core payment rails
- Led regulatory technology modernization program across 5 global regulatory frameworks
- Partnered with Engineering, Legal, Compliance, and Risk to ship 12 major platform releases

Morgan Stanley | Associate Product Manager → Product Manager
- Built fixed income trading desk tools reducing order execution latency by 35%
- Shipped client reporting platform serving $500B+ in AUM
- Led technical program for FINRA and SEC reporting automation

EDUCATION
Columbia Business School — MBA
University of [X] — BS Computer Science

SKILLS
Product: 0-to-1 product development, roadmap strategy, OKRs, PRDs, stakeholder alignment
Technical: RAG systems, MCP frameworks, n8n, Python, SQL, REST APIs, LLM integration
Domain: Fintech infrastructure, AML/KYC, regulatory technology, payments, DeFi
`;

const SYSTEM_PROMPT = `You are an expert technical resume writer specializing in senior fintech and AI product roles.

You are given a master resume and a job description. Your task is to tailor specific sections of the resume to better match the job description language and priorities — WITHOUT changing any facts, titles, dates, or companies.

Rules:
1. Mirror the exact language and terminology used in the JD
2. Lead each bullet with the most relevant achievement for this specific role
3. Keep all numbers and metrics accurate
4. Do not add skills or experiences that are not in the master resume
5. Keep bullets under 2 lines each
6. The headline should be a 5-8 word role-specific tagline

Return ONLY valid JSON in this exact schema (no markdown, no extra text):
{
  "headline": "<5-8 word tailored headline>",
  "summary": "<3-4 sentence tailored professional summary>",
  "coinbaseBullets": ["<bullet 1>", "<bullet 2>", "<bullet 3>"],
  "goldmanBullets": ["<bullet 1>", "<bullet 2>", "<bullet 3>"]
}`;

const job = $json;

const userMessage = `MASTER RESUME:
${MASTER_RESUME}

---

JOB DESCRIPTION TO TAILOR FOR:
Title: ${job.title}
Company: ${job.company}

${job.description}`;

const requestBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1500,
  system: SYSTEM_PROMPT,
  messages: [
    {
      role: 'user',
      content: userMessage
    }
  ]
};

return [
  {
    json: {
      ...job,
      _resumeRequestBody: JSON.stringify(requestBody)
    }
  }
];

const apiResponse = $json;
const prevJob = $node['Prepare Resume Tailoring Request'].json;

let headline = '';
let summary = '';
let coinbaseBullets = [];
let goldmanBullets = [];
let resumeError = null;

try {
  if (apiResponse.error) {
    throw new Error(`Claude API error: ${apiResponse.error.message}`);
  }

  const content = apiResponse?.content?.[0]?.text;
  if (!content) throw new Error('No content in Claude response');

  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  headline = parsed.headline || '';
  summary = parsed.summary || '';
  coinbaseBullets = Array.isArray(parsed.coinbaseBullets) ? parsed.coinbaseBullets : [];
  goldmanBullets = Array.isArray(parsed.goldmanBullets) ? parsed.goldmanBullets : [];

} catch (err) {
  resumeError = err.message;
}

return [
  {
    json: {
      date: new Date().toISOString().split('T')[0],
      company: prevJob.company,
      title: prevJob.title,
      score: prevJob.score,
      fitReasons: prevJob.fitReasons,
      gaps: prevJob.gaps,
      summary: prevJob.summary,
      applicationUrl: prevJob.applicationUrl,
      salary: prevJob.salary,
      source: prevJob.source,
      tailoredHeadline: headline,
      tailoredSummary: summary,
      coinbaseBullets: coinbaseBullets.join(' | '),
      goldmanBullets: goldmanBullets.join(' | '),
      resumeStatus: resumeError ? `Error: ${resumeError}` : 'Tailored',
      resumeError
    }
  }
];

// Collect all high-score jobs and format the top 5 for Slack

const jobs = $input.all().map(item => item.json);

// Sort by score descending
const sorted = jobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const top5 = sorted.slice(0, 5);

if (top5.length === 0) {
  return [
    {
      json: {
        slackMessage: '*Job Discovery Report — No high-score jobs found today.*\nCheck Apify actor logs and verify scraping is working.'
      }
    }
  ];
}

const today = new Date().toISOString().split('T')[0];

let blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `Job Discovery Report — ${today}`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${sorted.length} high-scoring jobs found today. Top ${top5.length} below:*`
    }
  },
  { type: 'divider' }
];

top5.forEach((job, i) => {
  const scoreEmoji = job.score >= 9 ? '🔥' : job.score >= 8 ? '⭐' : '✅';
  const fitText = Array.isArray(job.fitReasons) ? job.fitReasons.slice(0, 2).join(' • ') : job.summary || '';

  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `${scoreEmoji} *${job.company}* | ${job.title}\n*Score:* ${job.score}/10${job.salary ? ` | *Salary:* ${job.salary}` : ''}\n*Why it fits:* ${fitText}${job.tailoredHeadline ? `\n*Tailored headline:* _${job.tailoredHeadline}_` : ''}`
    },
    accessory: job.applicationUrl ? {
      type: 'button',
      text: { type: 'plain_text', text: 'Apply' },
      url: job.applicationUrl
    } : undefined
  });
  blocks.push({ type: 'divider' });
});

blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: `All ${sorted.length} results logged to Google Sheets. Workflow 2 (outreach) runs at 8AM for score ≥ 8 jobs.`
    }
  ]
});

return [
  {
    json: {
      slackBlocks: JSON.stringify(blocks),
      slackText: top5.map(j => `${j.company} | ${j.title} | ${j.score}/10 | ${j.summary}`).join('\n'),
      totalFound: sorted.length
    }
  }
];
